-- Local-first business database schema. All timestamps are UTC ISO-8601 TEXT.
CREATE TABLE IF NOT EXISTS schema_migrations (version TEXT PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS identities (id TEXT PRIMARY KEY, provider TEXT NOT NULL, provider_account_id TEXT NOT NULL, display_name TEXT, email TEXT, avatar_url TEXT, profile_json TEXT, last_synced_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(provider, provider_account_id));
CREATE TABLE IF NOT EXISTS departments (id TEXT PRIMARY KEY, provider_id TEXT UNIQUE, name TEXT NOT NULL, parent_id TEXT REFERENCES departments(id), updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS org_members (identity_id TEXT PRIMARY KEY REFERENCES identities(id), manager_identity_id TEXT REFERENCES identities(id), department_id TEXT REFERENCES departments(id), role TEXT NOT NULL DEFAULT 'member' CHECK(role IN ('member','manager','admin')), status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','disabled')), updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_org_members_manager ON org_members(manager_identity_id);
CREATE TABLE IF NOT EXISTS secret_refs (id TEXT PRIMARY KEY, provider TEXT NOT NULL, subject_id TEXT NOT NULL, keychain_key TEXT NOT NULL UNIQUE, expires_at TEXT, rotated_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(provider, subject_id));
CREATE TABLE IF NOT EXISTS work_items (id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('task','email_action','meeting_action','report_action')), title TEXT NOT NULL, description TEXT, status TEXT NOT NULL DEFAULT 'inbox' CHECK(status IN ('inbox','planned','in_progress','blocked','done','cancelled')), priority TEXT NOT NULL DEFAULT 'P1' CHECK(priority IN ('P0','P1','P2')), due_at TEXT, scheduled_for TEXT, completed_at TEXT, cancelled_at TEXT, owner_identity_id TEXT REFERENCES identities(id), source_type TEXT, source_external_id TEXT, source_url TEXT, source_snapshot_json TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(source_type, source_external_id));
CREATE INDEX IF NOT EXISTS idx_work_items_today ON work_items(owner_identity_id,status,scheduled_for,due_at);
CREATE INDEX IF NOT EXISTS idx_work_items_active_due ON work_items(status,due_at) WHERE status IN ('inbox','planned','in_progress','blocked');
CREATE TABLE IF NOT EXISTS work_item_events (id TEXT PRIMARY KEY, work_item_id TEXT NOT NULL REFERENCES work_items(id) ON DELETE CASCADE, event_type TEXT NOT NULL, from_status TEXT, to_status TEXT, payload_json TEXT, occurred_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_work_item_events_item_time ON work_item_events(work_item_id,occurred_at DESC);
CREATE TABLE IF NOT EXISTS goals (id TEXT PRIMARY KEY, period_type TEXT NOT NULL DEFAULT 'week' CHECK(period_type='week'), period_start TEXT NOT NULL, period_end TEXT NOT NULL, title TEXT NOT NULL, detail TEXT, manual_progress INTEGER NOT NULL DEFAULT 0 CHECK(manual_progress BETWEEN 0 AND 100), next_step TEXT, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','completed','cancelled')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_goals_period ON goals(period_start,created_at);
CREATE TABLE IF NOT EXISTS goal_work_items (goal_id TEXT NOT NULL REFERENCES goals(id) ON DELETE CASCADE, work_item_id TEXT NOT NULL REFERENCES work_items(id) ON DELETE CASCADE, created_at TEXT NOT NULL, PRIMARY KEY(goal_id,work_item_id));
CREATE TABLE IF NOT EXISTS daily_reports (id TEXT PRIMARY KEY, owner_identity_id TEXT REFERENCES identities(id), report_date TEXT NOT NULL, source TEXT NOT NULL DEFAULT 'manual' CHECK(source IN ('manual','dingtalk')), source_report_id TEXT, sync_status TEXT NOT NULL DEFAULT 'draft' CHECK(sync_status IN ('draft','pending_sync','synced','failed')), summary TEXT, completed_snapshot_json TEXT NOT NULL DEFAULT '[]', next_actions_snapshot_json TEXT NOT NULL DEFAULT '[]', raw_payload_ref TEXT, submitted_at TEXT, synced_at TEXT, source_updated_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(owner_identity_id,report_date), UNIQUE(source,source_report_id));
CREATE INDEX IF NOT EXISTS idx_daily_reports_owner_date ON daily_reports(owner_identity_id,report_date DESC);
CREATE TABLE IF NOT EXISTS report_issues (id TEXT PRIMARY KEY, report_id TEXT NOT NULL REFERENCES daily_reports(id) ON DELETE CASCADE, issue_type TEXT NOT NULL CHECK(issue_type IN ('blocker','risk','decision_needed','cooperation_needed')), title TEXT NOT NULL, detail TEXT, severity TEXT NOT NULL DEFAULT 'medium' CHECK(severity IN ('low','medium','high','critical')), status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','acknowledged','resolved','closed')), assignee_identity_id TEXT REFERENCES identities(id), resolved_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS report_feedback (id TEXT PRIMARY KEY, report_id TEXT NOT NULL REFERENCES daily_reports(id) ON DELETE CASCADE, issue_id TEXT REFERENCES report_issues(id) ON DELETE SET NULL, author_identity_id TEXT REFERENCES identities(id), feedback_type TEXT NOT NULL CHECK(feedback_type IN ('read','decision','reminder','recognition','comment')), content TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sync_jobs (id TEXT PRIMARY KEY, provider TEXT NOT NULL, scope TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('queued','running','succeeded','failed')), cursor_json TEXT, started_at TEXT, finished_at TEXT, next_run_at TEXT, error_code TEXT, error_message TEXT, metrics_json TEXT);
CREATE INDEX IF NOT EXISTS idx_sync_jobs_pending ON sync_jobs(status,next_run_at);
CREATE TABLE IF NOT EXISTS sync_checkpoints (provider TEXT NOT NULL, scope_key TEXT NOT NULL, cursor_json TEXT, last_success_at TEXT, last_attempt_at TEXT, last_error_code TEXT, PRIMARY KEY(provider,scope_key));
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY, recipient_identity_id TEXT REFERENCES identities(id), type TEXT NOT NULL, payload_json TEXT NOT NULL, read_at TEXT, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_notifications_recipient_unread ON notifications(recipient_identity_id,read_at,created_at DESC);
CREATE TABLE IF NOT EXISTS audit_events (id TEXT PRIMARY KEY, actor_identity_id TEXT REFERENCES identities(id), action TEXT NOT NULL, target_type TEXT NOT NULL, target_id TEXT, metadata_json TEXT, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_audit_events_created ON audit_events(created_at DESC);
